import React from 'react';
import {
  FaBolt,
  FaBorderAll,
  FaBroom,
  FaBug,
  FaCamera,
  FaCar,
  FaHammer,
  FaHardHat,
  FaHome,
  FaPaintRoller,
  FaRoad,
  FaShieldAlt,
  FaSnowflake,
  FaTint,
  FaTools,
  FaTree,
  FaTruck,
  FaWindowMaximize,
  FaWrench,
} from 'react-icons/fa';
import type { IconKey } from '../lib/viewModel';

const MAP: Record<IconKey, React.ComponentType> = {
  roof: FaHardHat,
  home: FaHome,
  hammer: FaHammer,
  paint: FaPaintRoller,
  water: FaTint,
  tree: FaTree,
  bolt: FaBolt,
  wrench: FaWrench,
  broom: FaBroom,
  truck: FaTruck,
  shield: FaShieldAlt,
  window: FaWindowMaximize,
  fence: FaBorderAll,
  concrete: FaRoad,
  snow: FaSnowflake,
  bug: FaBug,
  car: FaCar,
  camera: FaCamera,
  tools: FaTools,
};

/** Renders the icon chosen for a service by `iconForService()`. */
export default function ServiceIcon({ name }: { name: IconKey }) {
  const Icon = MAP[name] ?? FaTools;
  return <Icon />;
}
